<?php if(!$selected['archived']):?>
<?php if($due['total']>0):?><details class="fi-disclosure"><summary>Record payment for this installment</summary><form method="post"><?php debt_fields('payment',$selected);?><input type="hidden" name="installment_id" value="<?= (int)$installment['installment_id'] ?>"><div class="fi-form-grid"><label>Paid on<input class="form-control" type="date" name="paid_on" min="<?= fi_h($selected['opened_on']) ?>" max="<?= $today ?>" value="<?= $today ?>" required></label><?php foreach(['principal'=>'Principal paid','interest'=>'Interest paid','fees'=>'Fees paid'] as $key=>$label):?><label><?= $label ?><input class="form-control" type="number" name="<?= $key ?>" min="0" max="<?= fi_amount($due[$key]) ?>" step="0.01" value="<?= fi_amount($due[$key]) ?>" required><small class="form-text">Up to <?= fi_h(fi_cash($due[$key]/100,$currency)) ?></small></label><?php endforeach;?><label class="fi-full">Note<input class="form-control" name="note" maxlength="255"></label></div><button class="btn btn-primary">Save installment payment</button></form></details><?php endif;?>
<details class="fi-disclosure"><summary>Edit due date & charges</summary><form method="post"><?php debt_fields('loan_edit',$selected);?><input type="hidden" name="installment_id" value="<?= (int)$installment['installment_id'] ?>"><div class="fi-form-grid"><label>Due date<input type="date" class="form-control" name="due_on" value="<?= fi_h($installment['due_on']) ?>" required></label><label>Planned interest<input type="number" class="form-control" name="planned_interest" min="<?= fi_h($installment['interest_paid']) ?>" step="0.01" value="<?= fi_h($installment['interest']) ?>" required></label><label>Planned fees<input type="number" class="form-control" name="planned_fees" min="<?= fi_h($installment['fees_paid']) ?>" step="0.01" value="<?= fi_h($installment['fees']) ?>" required></label></div><button class="btn btn-outline-primary">Save installment changes</button></form></details><?php endif;?></article>
